%Andrii Kholod EDIfu25/2 20255272 VAR 2
%complementary
[X, Y] = meshgrid(-2:0.1:2, -2:0.1:2) %[output:0a550556] %[output:66aaa44a]

Z = 1 - (X.^2 + Y.^2) %[output:45d05f07]
figure('Name', 'Features of surf function', 'Position', [100, 100, 1200, 400]); %[output:5b54a906]

subplot(1, 3, 1);        %[output:5b54a906]
surf(X, Y, Z); %[output:5b54a906]
shading interp;    %[output:5b54a906]
colormap("spring") %[output:5b54a906]
h = camlight('left');        %[output:5b54a906]
lighting gouraud;       %[output:5b54a906]
title('a) camlight effect'); %[output:5b54a906]
xlabel('X'); ylabel('Y'); zlabel('Z'); %[output:5b54a906]
% for i = 1:36
%     camorbit(10, 0);
%     camlight(h, 'left'); 
%     drawnow; 
%     pause(0.125);
% end


subplot(1, 3, 2);        %[output:5b54a906]
surfc(X, Y, Z);  %[output:5b54a906]
shading interp; %[output:5b54a906]
title('b) contour to main axis'); %[output:5b54a906]
xlabel('X'); ylabel('Y'); zlabel('Z'); %[output:5b54a906]


subplot(1, 3, 3);        %[output:5b54a906]
% surf(X, Y, Z);
% shading interp;
% alpha(0.6);             
% title('c) semitransparent surface');
% xlabel('X'); ylabel('Y'); zlabel('Z');


contour3(X, Y, Z) %[output:5b54a906]




